package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/branches") public class BranchController{private final JdbcClient db;public BranchController(JdbcClient db){this.db=db;}public record Branch(UUID id,String code,String documentCode,String name,String address,String phone){}@GetMapping List<Branch> list(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);return db.sql("select id,code,document_code,name,address,phone from amcservice.branches where tenant_id=:t and active order by name").param("t",u.tenantId()).query(Branch.class).list();}}
